SetColumns(0);SetQuitOnError(true);SetNthreads(1);Alarm(60);tt:=Cputime();root:="work/deg10/continuation_20261031b/M3N18/";Attach(root cat"inputs/fast_full_aut_hash_m3_18_root.m");dat:=eval Read(root cat"endomorphism_gluing/actual_target13_points.m");k:=GF(13);PK:=PolynomialRing(k);K<z>:=ext<k|PK!dat[3]>;a:=dat[4][1];b:=dat[4][2];qt:=[Evaluate(PK!c,z):c in a[3]];target:=[Evaluate(PK!c,z):c in b[3]];q,t:=Explode(qt);E:=EllipticCurve([K|q*t-q+t+2,0,q*t^2-q*t+t,0,0]);P:=E![0,0];Q:=E![-t,t^2];T:=9*Q;E1,phi:=IsogenyFromKernel(E,PolynomialRing(K).1-T[1]);xd:=-aInvariants(E)[2]-aInvariants(E)[1]^2/4-2*T[1];aa:=aInvariants(E1);Td:=E1![xd,-(aa[1]*xd+aa[3])/2];assert 2*Td eq E1!0 and Td ne E1!0;P1:=phi(P);Q1:=2*phi(Q)+Td;assert 3*P1 eq E1!0 and 18*Q1 eq E1!0 and 9*Q1 ne E1!0 and 6*Q1 ne E1!0;assert WeilPairing(P1,6*Q1,3)eq WeilPairing(P,6*Q,3);hits:=[* *];for par in M3EighteenRootAutParameters()do ac,bb,cc,dd:=Explode(par);PP:=ac*P1+6*bb*Q1;QQ:=cc*P1+dd*Q1;vv:=M3EighteenRootNormalizedPair(E1,PP,QQ);js:=[j:j in[0..4]|vv eq[x^(13^j):x in target]];if #js ne 0 then Append(~hits,[*par,js*]);end if;end for;Write(root cat"tau_cross13.m",Sprint(hits):Overwrite:=true);print "D31B_M318_TAU_CROSS13_COMPLETE",a[1],b[1],hits,Cputime(tt);quit;
